"""Naive, deliberately straightforward reference implementation of PROTOCOL 3.0.

Written directly from the protocol text with plain lists/dicts and full deep
copies for checkpoints.  Used only to cross-check the optimized submission.
"""
import json, sys
from bisect import bisect_right, insort
from copy import deepcopy


class RefPolicy:
    def __init__(self, spec):
        self.kind = spec['kind']
        self.spec = spec
        if self.kind == 'fifo':
            self.time = 0
        elif self.kind == 'sp':
            self.levels = dict(spec['levels'])
        elif self.kind == 'wfq':
            self.weights = dict(spec['weights'])
            self.V = 0
            self.F = {f: 0 for f in self.weights}

    def rank(self, flow, length, flow_size):
        k = self.kind
        if k == 'fifo':
            self.time += 1
            return self.time
        if k == 'sp':
            return self.levels[flow]
        if k == 'sff':
            return flow_size
        # wfq
        w = self.weights[flow]
        f = max(self.F[flow], self.V)
        f = f + -(-length * 1048576 // w)
        self.F[flow] = f
        return f

    def post_service(self, rank):
        if self.kind == 'wfq':
            self.V = max(self.V, rank)

    def set_weight(self, flow, w):
        self.weights[flow] = w

    def certificate(self):
        k = self.kind
        if k == 'fifo':
            return {"kind": "fifo", "time": self.time}
        if k == 'sp':
            return {"kind": "sp", "levels": [[f, self.levels[f]] for f in sorted(self.levels)]}
        if k == 'sff':
            return {"kind": "sff"}
        return {"kind": "wfq", "virtual_time": self.V,
                "weights": [[f, self.weights[f]] for f in sorted(self.weights)],
                "finish": [[f, self.F[f]] for f in sorted(self.F)]}


class RefRun:
    def __init__(self, spec):
        self.M = spec['banks']
        self.L = spec['load_balancers']
        self.fifo_bytes = spec['fifo_bytes']
        self.pifo_bytes = spec['pifo_bytes']
        self.refill_batch = spec['refill_batch']
        self.P = spec['sample_period']
        self.borders = list(spec['borders'])
        self.R = len(self.borders) - 1
        self.U = self.borders[-1]
        M = self.M
        self.C = [[[1 if q < (r % M) else 0 for r in range(self.R)] for q in range(M)]
                  for _ in range(self.L)]
        self.H = [0] * self.R
        self.t = 0
        self.p = 0
        self.l = 0
        self.a = 0
        self.policy = RefPolicy(spec['policy'])
        # queues: fifo[q] list of pkt dicts in arrival order
        #         pifo[q] list of pkt dicts sorted by (rank, ordinal)
        self.fifo = [[] for _ in range(M)]
        self.pifo = [[] for _ in range(M)]
        self.fifo_used = [0] * M
        self.pifo_used = [0] * M
        self.live = {}     # id -> pkt dict
        self.saves = {}
        self.log = []
        self.events = spec['events']

    # ---- helpers
    def classify(self, rank):
        x = min(rank, self.U - 1)
        return bisect_right(self.borders, x) - 1

    def select_bank(self, l, r):
        best, bestv = 0, self.C[l][0][r]
        for q in range(1, self.M):
            v = self.C[l][q][r]
            if v < bestv:
                bestv, best = v, q
        return best

    def snapshot(self):
        return deepcopy((self.t, self.p, self.l, self.a, self.borders, self.R,
                         self.U, self.C, self.H, self.fifo, self.pifo,
                         self.fifo_used, self.pifo_used, self.live,
                         self.policy))

    def restore(self, snap):
        (self.t, self.p, self.l, self.a, self.borders, self.R, self.U,
         self.C, self.H, self.fifo, self.pifo, self.fifo_used, self.pifo_used,
         self.live, self.policy) = deepcopy(snap)

    def do_sample(self, i):
        X = [0] * self.R
        for lb in self.C:
            for row in lb:
                for r in range(self.R):
                    X[r] += row[r]
        for l in range(self.L):
            for r in range(self.R):
                mn = min(self.C[l][q][r] for q in range(self.M))
                for q in range(self.M):
                    self.C[l][q][r] -= mn
        self.H = [self.H[r] // 2 + X[r] for r in range(self.R)]
        self.a = 0
        self.log.append([i, "sample", X, self.H])

    def refill(self, q):
        n = min(self.refill_batch, len(self.fifo[q]))
        cands = []
        for _ in range(n):
            pkt = self.fifo[q].pop(0)
            self.fifo_used[q] -= pkt['length']
            cands.append(pkt)
        cands.sort(key=lambda d: (d['rank'], d['oid']))
        budget = self.pifo_bytes - self.pifo_used[q]
        total = 0
        keep = 0
        for pkt in cands:
            if total + pkt['length'] <= budget:
                total += pkt['length']
                keep += 1
            else:
                break
        for pkt in cands[:keep]:
            insort(self.pifo[q], pkt) if False else None
            self.pifo[q].append(pkt)
            self.pifo_used[q] += pkt['length']
        self.pifo[q].sort(key=lambda d: (d['rank'], d['oid']))
        evicted = []
        for pkt in sorted(cands[keep:], key=lambda d: (d['rank'], d['oid']), reverse=True):
            del self.live[pkt['pktid']]
            evicted.append(pkt['pktid'])
        return evicted

    def serve(self, q, i, old_t, evicted):
        pkt = self.pifo[q].pop(0)
        self.pifo_used[q] -= pkt['length']
        del self.live[pkt['pktid']]
        self.policy.post_service(pkt['rank'])
        rank_error = sum(1 for o in self.live.values() if o['rank'] < pkt['rank'])
        lag = pkt['lag']
        for o in self.live.values():
            if o['rank'] < pkt['rank']:
                o['lag'] += 1
        self.log.append([i, "dequeue", old_t, q, pkt['pktid'], pkt['rank'],
                         rank_error, lag, evicted])

    def execute(self):
        for i, ev in enumerate(self.events):
            kind = ev[0]
            if kind == 'enqueue':
                pid, flow, length, flow_size = ev[1], ev[2], ev[3], ev[4]
                rank = self.policy.rank(flow, length, flow_size)
                r = self.classify(rank)
                l = self.l
                q = self.select_bank(l, r)
                acc = self.fifo_used[q] + length <= self.fifo_bytes
                if acc:
                    pkt = {'pktid': pid, 'flow': flow, 'length': length,
                           'flow_size': flow_size, 'rank': rank, 'oid': i,
                           'lag': 0, 'stage': 'fifo', 'bank': q}
                    self.fifo[q].append(pkt)
                    self.fifo_used[q] += length
                    self.live[pid] = pkt
                    self.C[l][q][r] += 1
                    self.a += 1
                self.l = (self.l + 1) % self.L
                self.log.append([i, "enqueue", pid, rank, l, r, q, acc])
                if acc and self.a == self.P:
                    self.do_sample(i)
            elif kind == 'dequeue':
                n = ev[1]
                for _ in range(n):
                    q = self.p
                    self.p = (self.p + 1) % self.M
                    old_t = self.t
                    self.t += 1
                    if self.pifo[q]:
                        evicted = self.refill_after_pop(q)
                        self.serve(q, i, old_t, evicted)
                    else:
                        evicted = self.refill(q)
                        if self.pifo[q]:
                            self.serve(q, i, old_t, evicted)
                        else:
                            self.log.append([i, "dequeue", old_t, q, None, None, 0, 0, evicted])
            elif kind == 'sample':
                self.do_sample(i)
            elif kind == 'repartition':
                new = list(ev[1])
                newR = len(new) - 1
                old = self.borders

                def proj(vals):
                    out = [0] * newR
                    for j in range(len(vals)):
                        m = vals[j]
                        if m == 0:
                            continue
                        b, c = old[j], old[j + 1]
                        span = c - b
                        for k in range(newR):
                            u, v = new[k], new[k + 1]
                            cl = lambda x: max(0, min(x, span))
                            out[k] += (m * cl(v - b)) // span - (m * cl(u - b)) // span
                    return out
                self.C = [[proj(row) for row in lb] for lb in self.C]
                self.H = proj(self.H)
                self.borders = new
                self.R = newR
                self.U = new[-1]
                self.log.append([i, "repartition", newR])
            elif kind == 'cancel':
                pid = ev[1]
                pkt = self.live.get(pid)
                if pkt is None:
                    self.log.append([i, "cancel", pid, None, None, None])
                else:
                    q = pkt['bank']
                    if pkt['stage'] == 'fifo':
                        self.fifo[q].remove(pkt)
                        self.fifo_used[q] -= pkt['length']
                    else:
                        self.pifo[q].remove(pkt)
                        self.pifo_used[q] -= pkt['length']
                    del self.live[pid]
                    self.log.append([i, "cancel", pid, pkt['stage'], q, pkt['lag']])
            elif kind == 'inspect':
                pid = ev[1]
                pkt = self.live.get(pid)
                if pkt is None:
                    self.log.append([i, "inspect", pid, None])
                else:
                    self.log.append([i, "inspect", pid, [pkt['rank'], pkt['bank'],
                                       pkt['stage'], pkt['length'], pkt['flow'], pkt['lag']]])
            elif kind == 'weight':
                self.policy.set_weight(ev[1], ev[2])
                self.log.append([i, "weight", ev[1], ev[2]])
            elif kind == 'save':
                self.saves[ev[1]] = self.snapshot()
                self.log.append([i, "save", ev[1]])
            elif kind == 'restore':
                self.restore(self.saves[ev[1]])
                self.log.append([i, "restore", ev[1]])
        return self

    def refill_after_pop(self, q):
        # pop head, policy feedback, then refill
        return self._pending

    def final_state(self):
        queues = []
        for q in range(self.M):
            queues.append({"fifo": [p['pktid'] for p in self.fifo[q]],
                           "pifo": [p['pktid'] for p in sorted(self.pifo[q], key=lambda d: (d['rank'], d['oid']))],
                           "fifo_bytes": self.fifo_used[q],
                           "pifo_bytes": self.pifo_used[q]})
        lags = sorted([[pid, p['lag']] for pid, p in self.live.items()])
        return {"tick": self.t, "load_balancer": self.l, "service_bank": self.p,
                "sample_progress": self.a, "borders": list(self.borders),
                "counters": self.C, "history": self.H,
                "policy": self.policy.certificate(), "queues": queues, "lags": lags}


def run_request(request):
    runs = []
    for spec in request['runs']:
        runs.append({"log": RefRun(spec).execute().log,
                     "state": RefRun(spec).execute().final_state()})
    return {"runs": runs}


if __name__ == '__main__':
    print(json.dumps(run_request(json.load(sys.stdin)), separators=(',', ':')))
