#!/usr/bin/env python3
"""JSON entry point; all computation lives in the scheduling modules.

One UTF-8 JSON request is read through EOF, one JSON response is written and
the process exits zero.  Malformed batches (invalid UTF-8, malformed JSON,
duplicate keys at any depth, non-finite numbers, trailing JSON values) produce
exactly ``{"error":"invalid"}``.  Nothing but the response is written to
stdout.
"""
import json
import math
import sys
import traceback
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
from utils import run_request

ERROR = '{"error":"invalid"}'


def pairs(items):
    """Object hook rejecting duplicate keys at any depth."""
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError('duplicate key')
        result[key] = value
    return result


def reject_constant(value):
    raise ValueError('nonfinite number')


def finite(value):
    """Reject NaN/Infinity anywhere in the parsed request."""
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError('nonfinite number')
    elif isinstance(value, (dict, list)):
        for item in (value.values() if isinstance(value, dict) else value):
            finite(item)


def emit(text):
    try:
        sys.stdout.buffer.write(text.encode('utf-8'))
        sys.stdout.buffer.flush()
    except (BrokenPipeError, OSError):
        pass


def main():
    try:
        request = json.loads(sys.stdin.buffer.read().decode('utf-8'),
                             object_pairs_hook=pairs,
                             parse_constant=reject_constant)
        finite(request)
    except (ValueError, UnicodeError, RecursionError, MemoryError):
        emit(ERROR)
        return 0
    try:
        response = run_request(request)
        text = json.dumps(response, separators=(',', ':'), allow_nan=False)
    except Exception:
        # Unexpected schema deviation or internal failure: collapse to the
        # documented error object.  Diagnostics stay off stdout.
        traceback.print_exc()
        text = ERROR
    emit(text)
    return 0


if __name__ == '__main__':
    sys.exit(main())
